INSERT INTO "products" ("id", "model", "name", "category", "description", "brand_image_url", "image_url", "pdf_url", "features", "status", "created_at", "updated_at") VALUES ('104', 'JX-320', 'JX series jewellers weighing scale', 'Precision Balances', 'When trading in gold and precious metals, accuracy is paramount. The Essae JX Series jewellery balance delivers precision weighing results, making it the trusted choice for jewellers, bullion traders, and gem specialists. Designed with ergonomics, durability, and ease of use, the JX Series combines performance with elegance. Powered by both an AC adapter and an inbuilt rechargeable lithium ion battery, the JX Series ensures uninterrupted productivity. Its dark violet LCD with a white backlight displays results in large 13 mm digits, ensuring clear visibility even in busy retail environments.', 'https://res.cloudinary.com/hehl57yx/image/upload/v1789029323/weighing-balance/products/oafswkx1mdyx1ztli2u3.png', 'https://res.cloudinary.com/hehl57yx/image/upload/v1789029326/weighing-balance/products/akknnnbs9ufquxqnj80t.png', 'https://res.cloudinary.com/hehl57yx/image/upload/v1789129535/weighing-balance/products/pdfs/CAT-JX-Series-095.pdf', 'The Essae JX Series jewellery balance delivers precision weighing results, 
 Designed with ergonomics, durability, and ease of use, 
Its dark violet LCD with a white backlight displays results in large 13 mm digits,', TRUE, '2026-09-10T08:35:28.625Z', '2026-09-11T12:25:40.955Z') ON CONFLICT ("id") DO UPDATE SET "model" = EXCLUDED."model", "name" = EXCLUDED."name", "category" = EXCLUDED."category", "description" = EXCLUDED."description", "brand_image_url" = EXCLUDED."brand_image_url", "image_url" = EXCLUDED."image_url", "pdf_url" = EXCLUDED."pdf_url", "features" = EXCLUDED."features", "status" = EXCLUDED."status", "updated_at" = EXCLUDED."updated_at";
INSERT INTO "products" ("id", "model", "name", "category", "description", "brand_image_url", "image_url", "pdf_url", "features", "status", "created_at", "updated_at") VALUES ('105', 'HT/HTR', 'HT/HTR SERIES Analytical balance', 'Analytical balances', 'The HT/HTR Series analytical weighing scale is built on the highly reliable tuning fork sensing technology, delivering unmatched accuracy and stability. With the option of an in built calibration weight, it offers versatile functions such as weighing, counting, percentage, unit conversion, and density measurement. Compact, safe, and energy efficient, it is ideal for QC, laboratory, and research scientists who demand precision and convenience.', 'https://res.cloudinary.com/hehl57yx/image/upload/v1789032808/weighing-balance/products/uwxs5j1ikkui98uhzztl.png', 'https://res.cloudinary.com/hehl57yx/image/upload/v1789032810/weighing-balance/products/za8o8i2bzshzaub06ah8.png', 'https://res.cloudinary.com/hehl57yx/image/upload/v1789129622/weighing-balance/products/pdfs/CAT-HT-HTR.pdf', 'High accuracy and precision
Tuning Fork Technology ensures consistent results with minimal drift.

Compact and safe design
Simple structure with fewer parts enhances durability and safety.

Plug and perform convenience
Reduced warm up time by 90% for faster workflows

Multi mode functionality
Weighing, counting, unit conversion, and density measurement.

Optional In built calibration
Eliminates external calibration needs for hassle free operation.', TRUE, '2026-09-10T09:33:35.666Z', '2026-09-11T12:27:11.232Z') ON CONFLICT ("id") DO UPDATE SET "model" = EXCLUDED."model", "name" = EXCLUDED."name", "category" = EXCLUDED."category", "description" = EXCLUDED."description", "brand_image_url" = EXCLUDED."brand_image_url", "image_url" = EXCLUDED."image_url", "pdf_url" = EXCLUDED."pdf_url", "features" = EXCLUDED."features", "status" = EXCLUDED."status", "updated_at" = EXCLUDED."updated_at";
INSERT INTO "products" ("id", "model", "name", "category", "description", "brand_image_url", "image_url", "pdf_url", "features", "status", "created_at", "updated_at") VALUES ('106', '232C', 'AJ Series Precision balance', 'Precision Balances', 'The AJ Series precision balance is designed for laboratories, jewellery businesses, and industrial applications where accuracy and reliability are non negotiable. Compact yet powerful, it combines advanced tuning fork sensor technology with user friendly features to deliver consistent results every time.', 'https://res.cloudinary.com/hehl57yx/image/upload/v1789033154/weighing-balance/products/s1sefxuvrm7xmmyjtwoc.png', 'https://res.cloudinary.com/hehl57yx/image/upload/v1789033156/weighing-balance/products/qpvrm7lqvxpkafyjkz7y.png', 'https://res.cloudinary.com/hehl57yx/image/upload/v1789129579/weighing-balance/products/pdfs/CAT-AJ.pdf', 'High accuracy
With MMTS technology, it ensures precise measurements for laboratory experiments and jewellery weighing.

Ease of operation
Simple interface with clear display for quick, error free readings.

Versatile connectivity
Options to connect with computers or printers for seamless data management.

Rechargeable battery backup
With the optional rechargeable battery, you can carry the AJ Series anywhere you need perfect for mobile operations or environments where power access is limited.

Reliable support
Backed by Essae’s nationwide service and customer care network.', TRUE, '2026-09-10T09:39:33.277Z', '2026-09-11T12:26:32.812Z') ON CONFLICT ("id") DO UPDATE SET "model" = EXCLUDED."model", "name" = EXCLUDED."name", "category" = EXCLUDED."category", "description" = EXCLUDED."description", "brand_image_url" = EXCLUDED."brand_image_url", "image_url" = EXCLUDED."image_url", "pdf_url" = EXCLUDED."pdf_url", "features" = EXCLUDED."features", "status" = EXCLUDED."status", "updated_at" = EXCLUDED."updated_at";
INSERT INTO "products" ("id", "model", "name", "category", "description", "brand_image_url", "image_url", "pdf_url", "features", "status", "created_at", "updated_at") VALUES ('107', 'LF-225DR', 'LF-225DR Semi micro balance', 'Semi Micro Balances', 'The Essae LF-225DR Semi micro balance is engineered for laboratories and industries that demand uncompromising precision. With an exceptional readability of 0.01 mg, this micro weight machine ensures reliable results for advanced research and analysis. Built on electro magnetic force compensation technology, the LF-225DR delivers superior stability, minimal temperature drift, and consistent performance compared to conventional balances. Compact yet robust, it is the ideal choice for pharma QC labs, chemical research, and material testing, where accuracy and repeatability are critical.', 'https://res.cloudinary.com/hehl57yx/image/upload/v1789033914/weighing-balance/products/gw05221czr5bpx4grywm.png', 'https://res.cloudinary.com/hehl57yx/image/upload/v1789033916/weighing-balance/products/o4kj9clfkksreh5aysym.png', 'https://res.cloudinary.com/hehl57yx/raw/upload/v1789033927/weighing-balance/products/pdfs/xtf0euzkm9aybhitgfoo', 'High precision readability
0.01 mg resolution for micro level weighing.

Reliable technology
Electro magnetic force compensation ensures accuracy with low temperature drift.

User friendly design
Intuitive interface and ergonomic layout for smooth operation.

Versatile applications
Suitable for pharma QC, R&D labs, chemical analysis, and academic institutions.

Trusted Essae quality
Backed by calibration certificates and after sales support.', TRUE, '2026-09-10T09:52:06.495Z', '2026-09-10T09:52:06.496Z') ON CONFLICT ("id") DO UPDATE SET "model" = EXCLUDED."model", "name" = EXCLUDED."name", "category" = EXCLUDED."category", "description" = EXCLUDED."description", "brand_image_url" = EXCLUDED."brand_image_url", "image_url" = EXCLUDED."image_url", "pdf_url" = EXCLUDED."pdf_url", "features" = EXCLUDED."features", "status" = EXCLUDED."status", "updated_at" = EXCLUDED."updated_at";
INSERT INTO "products" ("id", "model", "name", "category", "description", "brand_image_url", "image_url", "pdf_url", "features", "status", "created_at", "updated_at") VALUES ('108', 'BA-6TE', 'A&D Borealis BA-T/BA Series', 'Semi Micro Balances', 'Delivers ultra‑high precision as a microbalance, combining advanced environmental control with intuitive laboratory operation.', 'https://res.cloudinary.com/hehl57yx/image/upload/v1789035349/weighing-balance/products/qiezravnkgconvkyc8d3.png', 'https://res.cloudinary.com/hehl57yx/image/upload/v1789035353/weighing-balance/products/fsdha9fdvglh52ufmi4e.png', 'https://res.cloudinary.com/hehl57yx/raw/upload/v1789035370/weighing-balance/products/pdfs/xjyupbkgzw79sp5n6ttu', '5" color touch screen display makes operation a breeze
Auto-Self Internal Calibration feature to adjust for temperature variations, ensuring consistent results
Standard external ionizer helps to eliminate errors due to static electricity
Automatic doors controlled by IR sensors allow for smooth and efficient access to the weighing chamber
Reverse backlit LCD display can be easily seen at a distance and at an angle
Touchless, quiet operation
Supports data protection with four user permission levels', TRUE, '2026-09-10T10:16:09.609Z', '2026-09-10T10:16:09.610Z') ON CONFLICT ("id") DO UPDATE SET "model" = EXCLUDED."model", "name" = EXCLUDED."name", "category" = EXCLUDED."category", "description" = EXCLUDED."description", "brand_image_url" = EXCLUDED."brand_image_url", "image_url" = EXCLUDED."image_url", "pdf_url" = EXCLUDED."pdf_url", "features" = EXCLUDED."features", "status" = EXCLUDED."status", "updated_at" = EXCLUDED."updated_at";
INSERT INTO "products" ("id", "model", "name", "category", "description", "brand_image_url", "image_url", "pdf_url", "features", "status", "created_at", "updated_at") VALUES ('109', 'BH-T/BH Series', 'BH-T/BH Series', 'Semi Micro Balances', 'The BH-T series offers maximum operability, enhanced functionality, and a broader range of solutions for advanced weighing tasks. All models include an external ionizer (static eliminator), automatic doors, multiple draft prevention safeguards, and intuitive navigation to streamline your workflow.', 'https://res.cloudinary.com/hehl57yx/image/upload/v1789036130/weighing-balance/products/d14sxewnhjcf2ctkkdcu.png', 'https://res.cloudinary.com/hehl57yx/image/upload/v1789036133/weighing-balance/products/i65mby0oymoiifqkkpjg.png', 'https://res.cloudinary.com/hehl57yx/image/upload/v1789113660/weighing-balance/products/pdfs/ba-t.pdf', '5″ color touch screen display makes operation a breeze
Auto-Self Internal Calibration feature to adjust for temperature variations, ensuring consistent results
Standard external ionizer helps to eliminate errors due to static electricity
Automatic doors controlled by IR sensors allow for smooth and efficient access to the weighing chamber', TRUE, '2026-09-10T10:29:21.098Z', '2026-09-11T08:01:34.422Z') ON CONFLICT ("id") DO UPDATE SET "model" = EXCLUDED."model", "name" = EXCLUDED."name", "category" = EXCLUDED."category", "description" = EXCLUDED."description", "brand_image_url" = EXCLUDED."brand_image_url", "image_url" = EXCLUDED."image_url", "pdf_url" = EXCLUDED."pdf_url", "features" = EXCLUDED."features", "status" = EXCLUDED."status", "updated_at" = EXCLUDED."updated_at";
INSERT INTO "products" ("id", "model", "name", "category", "description", "brand_image_url", "image_url", "pdf_url", "features", "status", "created_at", "updated_at") VALUES ('110', 'GX-12001L', 'A&D Apollo GX-L/GF-L Series', 'Precision Balances', 'The GX-L High Capacity precision balances were designed for applications that require laboratory accuracy but with industrial protection. The EMFC weighing system is protected by a durable metal housing and offers a maximum capacity of 102 kg.  The swimg arm display offers a simple yet flexible solution for bench applications and the separate display models are ideal for use on the floor with a wall mounted display.', 'https://res.cloudinary.com/hehl57yx/image/upload/v1789036721/weighing-balance/products/enltin21ix8zex1cw6co.png', 'https://res.cloudinary.com/hehl57yx/image/upload/v1789036723/weighing-balance/products/jqcishsoam1tzeazwjee.png', 'https://res.cloudinary.com/hehl57yx/raw/upload/v1789036741/weighing-balance/products/pdfs/byzksooef3ln8unse9i6', 'Dedicated software WinCT-GXA-Filter
This software is for users who wish to install the GX-L/GF-L balance in an automated weighing system and adjust its response settings beyond the standard settings.

Parameter setting software WinCT-ParamSet
This software can read and change the internal settings of an A&D electronic balance all at once.', TRUE, '2026-09-10T10:39:00.246Z', '2026-09-10T10:39:00.246Z') ON CONFLICT ("id") DO UPDATE SET "model" = EXCLUDED."model", "name" = EXCLUDED."name", "category" = EXCLUDED."category", "description" = EXCLUDED."description", "brand_image_url" = EXCLUDED."brand_image_url", "image_url" = EXCLUDED."image_url", "pdf_url" = EXCLUDED."pdf_url", "features" = EXCLUDED."features", "status" = EXCLUDED."status", "updated_at" = EXCLUDED."updated_at";
INSERT INTO "products" ("id", "model", "name", "category", "description", "brand_image_url", "image_url", "pdf_url", "features", "status", "created_at", "updated_at") VALUES ('114', 'GH Series', 'GH Series', 'Semi Micro Balances', 'High Performance up to 101g (GH-252), 0.01mg\nSemi-Micro Weighing Automatic Self-Calibration (GH)\nand Ergonomic Design Ethernet interface (GH-08)\nwith WinCT-Plus software makes data acquisition\nusing multiple GH models possible expanding your\nLocal Area Network System.', 'https://res.cloudinary.com/hehl57yx/image/upload/v1789114051/weighing-balance/products/rimfojgi3bowwv7xgf1m.png', 'https://res.cloudinary.com/hehl57yx/image/upload/v1789114053/weighing-balance/products/skf5ppddngdpjv38bguy.png', 'https://res.cloudinary.com/hehl57yx/image/upload/v1789114025/weighing-balance/products/pdfs/gh_hri.pdf', 'Standard RS-232C
Incorporates bi-directional communication with a PC, printer or other peripheral device.
Multiple Weighing Units
Uses programmable or standard units of measurement: g, mg, PCS (with ACAI* function), %, oz, ozt, ct, dwt, GN, tl, etc. *ACAI (Automatic Counting Accuracy Improvement)
Data Memory Function (GH models only)
200 PCS Weighing data without date and time
100 PCS Weighing with date and time
50 PCS Calibration history data
GLP/GMP/GCP/ISO Compliance ..........................................
Allows GLP or LIMS balance management by outputting the Balance ID number and data used to calibrate
the balance. This data can be output to A&D’s AD-8121B printer or a computer, indicating date, time,
Balance ID number, serial number and calibration data.
ID Number
The balance ID number can be set. It is used to identify the balance when GLP in use.
The ID number is memorized and maintained once it is fixed, even when the AC adapter is removed.
Auto Power On Function
Plug in the unit and it turns itself on without having to press the ON/OFF key.
Time & Date (GH models only)
Standard Time & Date Function complies with GLP and Interval Weighing in the Data Memory Function.
Interval Time Setting (GH models only)
Weighing intervals of 2, 5, 10, 30 seconds and 1, 2, 5, 10 minutes in the Data Memory Function', TRUE, '2026-09-11T08:07:35.080Z', '2026-09-11T08:07:35.081Z') ON CONFLICT ("id") DO UPDATE SET "model" = EXCLUDED."model", "name" = EXCLUDED."name", "category" = EXCLUDED."category", "description" = EXCLUDED."description", "brand_image_url" = EXCLUDED."brand_image_url", "image_url" = EXCLUDED."image_url", "pdf_url" = EXCLUDED."pdf_url", "features" = EXCLUDED."features", "status" = EXCLUDED."status", "updated_at" = EXCLUDED."updated_at";
INSERT INTO "products" ("id", "model", "name", "category", "description", "brand_image_url", "image_url", "pdf_url", "features", "status", "created_at", "updated_at") VALUES ('115', 'GR Series', 'GR Series', 'Semi Micro Balances', 'Easy Access Door\nSuperb “New Generation” Analysis! Superb “New Generation” Analysis!\nSpeedy & Simple Operation to Maximize Performanace\nOpen left or right side from front\nA unique system allows the user to conveniently\nopen or close the left or right side of the weighing\nchamber using a control lever.\nThis system allows quick and efficient access to\nthe weighing chamber.', 'https://res.cloudinary.com/hehl57yx/image/upload/v1789114877/weighing-balance/products/fmck5vuob5i52rmicbwt.png', 'https://res.cloudinary.com/hehl57yx/image/upload/v1789114878/weighing-balance/products/xc8blwldtck5cbhxislj.png', 'https://res.cloudinary.com/hehl57yx/image/upload/v1789114934/weighing-balance/products/pdfs/gr.pdf', 'One Touch Calibration
Allows quick calibration with one push of the CAL key.
Automatic Adjustable Environment Setting
Adapts automatically to the most suitable Environment Response Setting to
minimize adverse external effects. “FAST”, “MID” or “SLOW” is displayed.
Automatic Self Calibration
Performs self calibration automatically when a change of ambient
temperature exceeds the preset temperature range.
13 Multiple Weighing Units
g, mg, pcs, %, oz, ozt, ct, mom, dwt, GN, tl, t (tola), m (messghal)
Two Layer Housing
Durable construction minimizes negative effects of ambient temperature changes.
Splash Proof Keyboard and Display
Protected from dust and spills.
Data Memory Function
Stores up to 200 sets of weighing data. Data can be output using numerical codes', TRUE, '2026-09-11T08:21:17.172Z', '2026-09-11T08:22:26.972Z') ON CONFLICT ("id") DO UPDATE SET "model" = EXCLUDED."model", "name" = EXCLUDED."name", "category" = EXCLUDED."category", "description" = EXCLUDED."description", "brand_image_url" = EXCLUDED."brand_image_url", "image_url" = EXCLUDED."image_url", "pdf_url" = EXCLUDED."pdf_url", "features" = EXCLUDED."features", "status" = EXCLUDED."status", "updated_at" = EXCLUDED."updated_at";
INSERT INTO "products" ("id", "model", "name", "category", "description", "brand_image_url", "image_url", "pdf_url", "features", "status", "created_at", "updated_at") VALUES ('116', 'FX-i Series', 'FX-i Series', 'Precision Balances', 'High Performance and Functionality\nYou Can Afford\nBuilt on A&D''s cutting-edge sensor technology, the FX-i series is a\nhighly robust precision balance that delivers fast and accurate weighing\nwithout any frills, offering cost-effective solutions for a diverse array of\napplications.', 'https://res.cloudinary.com/hehl57yx/image/upload/v1789115222/weighing-balance/products/jqnb7riivjwdwksafyst.png', 'https://res.cloudinary.com/hehl57yx/image/upload/v1789115224/weighing-balance/products/etcm5ebg4g46etsuuu02.png', 'https://res.cloudinary.com/hehl57yx/image/upload/v1789115189/weighing-balance/products/pdfs/fx-i_fz-i.pdf', 'Multiple units of measure
You can easily select from: g, oz, lb, lb-oz, ozt, ct, mom, dwt, gr, pcs (counting mode), % (percent mode)
and a user-programmable unit for conversion applications. One additional unit from tl, tol, or N can be
added upon request.
GLP/GMP/GCP/ISO compliant output
For documentation requirements, the balance can output its manufacturer, model, serial number, ID
number, date + time*3, space for signature for calibration report, calibration test report, and title & end
blocks for a series of weighing results. *3 For the FZ-i models only. Please use the AD-8127 compact printer, which
has a calendar function, to print the date and time with the FX-i models.
Statistical calculation function (SCF)
The balance can display and output statistical calculation data including number of data, sum,
maximum, minimum, range (maximum–minimum), average, standard deviation, and coefficient of
variation to facilitate the analysis of measurements.', TRUE, '2026-09-11T08:27:08.314Z', '2026-09-11T08:27:08.314Z') ON CONFLICT ("id") DO UPDATE SET "model" = EXCLUDED."model", "name" = EXCLUDED."name", "category" = EXCLUDED."category", "description" = EXCLUDED."description", "brand_image_url" = EXCLUDED."brand_image_url", "image_url" = EXCLUDED."image_url", "pdf_url" = EXCLUDED."pdf_url", "features" = EXCLUDED."features", "status" = EXCLUDED."status", "updated_at" = EXCLUDED."updated_at";
INSERT INTO "products" ("id", "model", "name", "category", "description", "brand_image_url", "image_url", "pdf_url", "features", "status", "created_at", "updated_at") VALUES ('117', 'FZ-i Series', 'FZ-i Series', 'Precision Balances', 'High Performance and Functionality\nYou Can Afford\nBuilt on A&D''s cutting-edge sensor technology, the FZ-i/FX-i series is a\nhighly robust precision balance that delivers fast and accurate weighing\nwithout any frills, offering cost-effective solutions for a diverse array of\napplications.', 'https://res.cloudinary.com/hehl57yx/image/upload/v1789124865/weighing-balance/products/hykj04uslbvaxo0w2fgx.png', 'https://res.cloudinary.com/hehl57yx/image/upload/v1789124867/weighing-balance/products/mqyxrybyfp84vjh4zweg.png', 'https://res.cloudinary.com/hehl57yx/image/upload/v1789115189/weighing-balance/products/pdfs/fx-i_fz-i.pdf', 'Compact footprint: 198 mm × 294 mm
By taking advantage of our Compact Super Hybrid Sensor (C-SHS) technology◆, A&D significantly
reduced the size of a precision balance—25% smaller footprint than our conventional models,
making it ideal for installation and use in confined spaces. ◆ Patented
High-speed weighing with 1-second stabilization
The C-SHS combines the best of magnetic force restoration and single point parallelogram load sensing
technologies. This allows the C-SHS to realize a stabilization speed of just 1 second while maintaining
extremely high span stability. The FZ-i/FX-i series will maximize your productivity and efficiency.
Guarded against accidental overloading◆
An internal shock absorber*1
 protects the C-SHS from the adverse effects of vertical and transverse
overloading. This is especially effective if the balance is embedded in an automated weighing system
where actuator malfunctions are a possibility.', TRUE, '2026-09-11T11:07:52.733Z', '2026-09-11T11:07:52.733Z') ON CONFLICT ("id") DO UPDATE SET "model" = EXCLUDED."model", "name" = EXCLUDED."name", "category" = EXCLUDED."category", "description" = EXCLUDED."description", "brand_image_url" = EXCLUDED."brand_image_url", "image_url" = EXCLUDED."image_url", "pdf_url" = EXCLUDED."pdf_url", "features" = EXCLUDED."features", "status" = EXCLUDED."status", "updated_at" = EXCLUDED."updated_at";
INSERT INTO "products" ("id", "model", "name", "category", "description", "brand_image_url", "image_url", "pdf_url", "features", "status", "created_at", "updated_at") VALUES ('118', 'GF-3002A', 'GF-A(WP) Series', 'Analytical Balances', 'The GF-3002A is a precision weighing balance designed for accurate and reliable laboratory measurements.\nIt features a spacious stainless-steel weighing pan for convenient sample handling.\nThe clear digital display provides easy-to-read weight measurements.\nIts compact design makes it suitable for laboratories, educational institutions, and industrial applications.\nThe user-friendly keypad supports simple and efficient weighing operations.', 'https://res.cloudinary.com/hehl57yx/image/upload/v1789125251/weighing-balance/products/x0zvs8ofyzdlnbc3tbie.png', 'https://res.cloudinary.com/hehl57yx/image/upload/v1789125253/weighing-balance/products/iysnti8udj28hskjgsyr.png', 'https://res.cloudinary.com/hehl57yx/image/upload/v1789125247/weighing-balance/products/pdfs/gx-ae_gf-a.pdf', 'High-precision digital weighing performance
Stainless-steel weighing pan
Clear and easy-to-read LCD display
Compact and durable laboratory design
Suitable for laboratory and industrial weighing applications', TRUE, '2026-09-11T11:14:23.031Z', '2026-09-11T11:14:23.031Z') ON CONFLICT ("id") DO UPDATE SET "model" = EXCLUDED."model", "name" = EXCLUDED."name", "category" = EXCLUDED."category", "description" = EXCLUDED."description", "brand_image_url" = EXCLUDED."brand_image_url", "image_url" = EXCLUDED."image_url", "pdf_url" = EXCLUDED."pdf_url", "features" = EXCLUDED."features", "status" = EXCLUDED."status", "updated_at" = EXCLUDED."updated_at";
INSERT INTO "products" ("id", "model", "name", "category", "description", "brand_image_url", "image_url", "pdf_url", "features", "status", "created_at", "updated_at") VALUES ('119', 'GX-A(E/WP)  Series', 'GX-A(E/WP)  Series', 'Analytical balances', 'The GX-1003A is an analytical balance designed for precise weighing in laboratory and research environments.\nIts enclosed weighing chamber helps protect samples from external disturbances during measurement.\nThe stainless-steel weighing pan provides durability and easy cleaning.\nA large digital display allows users to read measurements quickly and clearly.\nIt is suitable for laboratories, quality control, research, and educational applications.', 'https://res.cloudinary.com/hehl57yx/image/upload/v1789126374/weighing-balance/products/a7vtgoa0fqyvmvqqt9jr.png', 'https://res.cloudinary.com/hehl57yx/image/upload/v1789126376/weighing-balance/products/btujyiece9euor8wgw0z.png', 'https://res.cloudinary.com/hehl57yx/image/upload/v1789125247/weighing-balance/products/pdfs/gx-ae_gf-a.pdf', 'High-accuracy analytical weighing
Protective draft-shield enclosure
Stainless-steel weighing pan
