INSERT INTO "products" ("id", "model", "name", "category", "description", "brand_image_url", "image_url", "pdf_url", "features", "status", "created_at", "updated_at") VALUES ('124', 'GX-L/GF-L Series', 'Apollo GX-L/GF-L Series', 'Precision Balances', 'The GX-L High Capacity precision balances were designed for applications that require laboratory accuracy but with industrial protection. The EMFC weighing system is protected by a durable metal housing and offers a maximum capacity of 102 kg.  The swimg arm display offers a simple yet flexible solution for bench applications and the separate display models are ideal for use on the floor with a wall mounted display.', 'https://res.cloudinary.com/hehl57yx/image/upload/v1789534177/weighing-balance/products/jobmyinpkqogl7zwbmnt.png', 'https://res.cloudinary.com/hehl57yx/image/upload/v1789534179/weighing-balance/products/y0fgzpqebttrgsueweau.png', 'https://res.cloudinary.com/hehl57yx/image/upload/v1789534174/weighing-balance/products/pdfs/gx-l_gf-l__1_.pdf', 'Dedicated software WinCT-GXA-Filter
This software is for users who wish to install the GX-L/GF-L balance in an automated weighing system and adjust its response settings beyond the standard settings.

Parameter setting software WinCT-ParamSet
This software can read and change the internal settings of an A&D electronic balance all at once.', TRUE, '2026-09-16T04:49:55.441Z', '2026-09-16T04:49:55.441Z') ON CONFLICT ("id") DO UPDATE SET "model" = EXCLUDED."model", "name" = EXCLUDED."name", "category" = EXCLUDED."category", "description" = EXCLUDED."description", "brand_image_url" = EXCLUDED."brand_image_url", "image_url" = EXCLUDED."image_url", "pdf_url" = EXCLUDED."pdf_url", "features" = EXCLUDED."features", "status" = EXCLUDED."status", "updated_at" = EXCLUDED."updated_at";
