INSERT INTO "products" ("id", "model", "name", "category", "description", "brand_image_url", "image_url", "pdf_url", "features", "status", "created_at", "updated_at") VALUES ('130', 'A&D ADFS Series', 'ADFS Series Industrial Floor Scales', 'Analytical balances', 'The A&D ADFS Series Industrial Floor Scales are designed for dependable and accurate weighing of heavy loads in industrial and commercial environments. They are available in capacities from 750 kg to 5,000 kg, making them suitable for a wide range of large-scale weighing applications. The series offers different readability options from 0.05 kg to 0.5 kg, depending on the capacity. The scales feature durable stainless-steel and MS-painted structures, along with a 7-inch LCD display and rechargeable battery options. The ADFS series also supports functions such as comparator weighing, multiple weighing units, Gross/Net/Tare, and a waterproof and corrosion-resistant load cell.', 'https://res.cloudinary.com/hehl57yx/image/upload/v1789544093/weighing-balance/products/ok79a3tllyph9x08hj4x.png', 'https://res.cloudinary.com/hehl57yx/image/upload/v1789544095/weighing-balance/products/mltofgjxvanzfw1a9ipm.png', 'https://res.cloudinary.com/hehl57yx/image/upload/v1789541202/weighing-balance/products/pdfs/2024-05-21-Platform-Scales-compressed.pdf', 'Durable stainless-steel and MS-painted structure options
7-inch LCD display with backlight
Waterproof and corrosion-resistant load cell
