INSERT INTO "products" ("id", "model", "name", "category", "description", "brand_image_url", "image_url", "pdf_url", "features", "status", "created_at", "updated_at") VALUES ('157', 'AD-4530', 'AD-4530', 'Multi-purpose Digital Indicator', 'AD-4530 is a compact digital indicator designed for strain-gauge sensors used in load, pressure, torque, and tension measurement applications. It provides stable and reliable measurement with digital zero, power-on zero, filtering, and calibration functions. The indicator supports comparator and hold functions for convenient monitoring and measurement. Optional interfaces provide relay, RS-232C/RS-485, and analog output capabilities for system integration.', 'https://res.cloudinary.com/hehl57yx/image/upload/v1789704423/weighing-balance/products/jeamke9s8ssglryuyrns.png', 'https://res.cloudinary.com/hehl57yx/image/upload/v1789704429/weighing-balance/products/fpalwrdv2ypzgoh3jtni.png', 'https://res.cloudinary.com/hehl57yx/image/upload/v1789704383/weighing-balance/products/pdfs/ad4530.ai', 'Digital indicator for strain-gauge sensors
Digital zero and power-on zero functions
Digital filter for stable measurement results
Hold and HI/OK/LO comparator functions
Optional RS-232C, RS-485, relay, and analog outputs', TRUE, '2026-09-18T04:07:23.216Z', '2026-09-18T04:07:23.216Z') ON CONFLICT ("id") DO UPDATE SET "model" = EXCLUDED."model", "name" = EXCLUDED."name", "category" = EXCLUDED."category", "description" = EXCLUDED."description", "brand_image_url" = EXCLUDED."brand_image_url", "image_url" = EXCLUDED."image_url", "pdf_url" = EXCLUDED."pdf_url", "features" = EXCLUDED."features", "status" = EXCLUDED."status", "updated_at" = EXCLUDED."updated_at";
INSERT INTO "products" ("id", "model", "name", "category", "description", "brand_image_url", "image_url", "pdf_url", "features", "status", "created_at", "updated_at") VALUES ('158', 'AD-4531A', 'AD-4531A', 'Multi-purpose Digital Indicator', 'AD-4531A is a digital indicator designed for monitoring output signals from bridge-type sensors. It provides high-speed signal conversion, stable measurement display, and convenient calibration without requiring an actual load. The unit includes hold and peak-hold functions and supports comparison outputs for monitoring HI/LO limits. It is suitable for industrial weighing and measurement systems requiring reliable signal indication and control.', 'https://res.cloudinary.com/hehl57yx/image/upload/v1789704545/weighing-balance/products/ixvomznqooqkkn2tvv7n.png', 'https://res.cloudinary.com/hehl57yx/image/upload/v1789704547/weighing-balance/products/xhhmueyfpwogukj8l1ly.png', 'https://res.cloudinary.com/hehl57yx/image/upload/v1789704540/weighing-balance/products/pdfs/ad4531a.pdf', 'High-speed 16-times-per-second A/D and D/A conversion
Calibration using the sensor''s rated mV/V output
Hold and peak-hold functions
HI/LO comparison with contact signal outputs
