INSERT INTO "products" ("id", "model", "name", "category", "description", "brand_image_url", "image_url", "pdf_url", "features", "status", "created_at", "updated_at") VALUES ('159', 'AD-4532B', 'AD-4532B', 'Multi-purpose Digital Indicator', 'AD-4532B is a high-speed digital indicator designed for strain-gauge sensors used in load, pressure, torque, tension, and other dynamic measurement applications. It provides 2000-times-per-second A/D conversion for fast and responsive measurements. The tricolor LED display makes measurement and test status easy to identify. Its advanced comparator, hold, calibration, and data-output functions make it suitable for industrial testing and automated measurement systems.', 'https://res.cloudinary.com/hehl57yx/image/upload/v1789705751/weighing-balance/products/r2jptwlrjbo8nwonziwj.png', 'https://res.cloudinary.com/hehl57yx/image/upload/v1789705753/weighing-balance/products/smxna2wdvsynwtve0noo.png', 'https://res.cloudinary.com/hehl57yx/image/upload/v1789705731/weighing-balance/products/pdfs/ad4532b.ai', 'Super-high-speed 2000 times/sec A/D conversion
Tricolor 6-digit LED display for clear measurement indication
5-level / 2D comparator for sequential testing applications
Sample, peak, bottom, and bipolar hold functions
Modbus-RTU, ±10 V analog output, with optional RS-232C, Ethernet, BCD, and 4–20 mA interfaces', TRUE, '2026-09-18T04:29:22.286Z', '2026-09-18T04:29:22.289Z') ON CONFLICT ("id") DO UPDATE SET "model" = EXCLUDED."model", "name" = EXCLUDED."name", "category" = EXCLUDED."category", "description" = EXCLUDED."description", "brand_image_url" = EXCLUDED."brand_image_url", "image_url" = EXCLUDED."image_url", "pdf_url" = EXCLUDED."pdf_url", "features" = EXCLUDED."features", "status" = EXCLUDED."status", "updated_at" = EXCLUDED."updated_at";
INSERT INTO "products" ("id", "model", "name", "category", "description", "brand_image_url", "image_url", "pdf_url", "features", "status", "created_at", "updated_at") VALUES ('160', 'AD4412-CW', 'AD4412-CW', 'Check Weighing Indicator', 'AD-4412-CW is a high-speed check-weighing indicator designed for automated weighing and conveyor-based applications. It features a 7-inch touch-panel color display and supports Passing, Stopping, and Static weighing modes. With high-speed sampling, feedback control, product management, and detailed weighing reports, it is suitable for production and quality-control environments.', 'https://res.cloudinary.com/hehl57yx/image/upload/v1789705947/weighing-balance/products/obsxtdyo8gk5fjrssw8v.png', 'https://res.cloudinary.com/hehl57yx/image/upload/v1789705949/weighing-balance/products/d7gz3w0kb4h4kdukhbnd.png', 'https://res.cloudinary.com/hehl57yx/image/upload/v1789705926/weighing-balance/products/pdfs/ad4412cw.pdf', '7-inch high-visibility color LCD touch panel
High-speed sampling at 4,000 times/second
Three weighing modes: Passing, Stopping, and Static
Stores up to 1,000 product settings
RS-232C, RS-485, LAN, USB and optional analog/relay interfaces', TRUE, '2026-09-18T04:32:38.089Z', '2026-09-18T04:32:38.089Z') ON CONFLICT ("id") DO UPDATE SET "model" = EXCLUDED."model", "name" = EXCLUDED."name", "category" = EXCLUDED."category", "description" = EXCLUDED."description", "brand_image_url" = EXCLUDED."brand_image_url", "image_url" = EXCLUDED."image_url", "pdf_url" = EXCLUDED."pdf_url", "features" = EXCLUDED."features", "status" = EXCLUDED."status", "updated_at" = EXCLUDED."updated_at";
INSERT INTO "products" ("id", "model", "name", "category", "description", "brand_image_url", "image_url", "pdf_url", "features", "status", "created_at", "updated_at") VALUES ('161', 'AD-4404', 'AD-4404', 'Check Weighing Indicator', 'AD-4404 is a high-speed check-weighing indicator designed for conveyor, roller, and platform weighing applications. It provides reliable weight checking with multiple weighing modes and high-speed sampling of 100 times per second. The large fluorescent display and bar graph make weight and comparison results easy to monitor. It is suitable for automated check-weighing, product classification, packing, and industrial weighing systems.', 'https://res.cloudinary.com/hehl57yx/image/upload/v1789706077/weighing-balance/products/g8kss0ps0zf1dwqq1jle.png', 'https://res.cloudinary.com/hehl57yx/image/upload/v1789706080/weighing-balance/products/igqhkzbhnqyeghjciitl.png', 'https://res.cloudinary.com/hehl57yx/image/upload/v1789706074/weighing-balance/products/pdfs/ad4404.pdf', 'High-speed sampling at 100 times/second
High display resolution up to 16,000 counts
Hi/OK/Lo and 5-level weight classification functions
Stores up to 100 sets of product and target-weight settings
Standard RS-485 and current-loop output with optional communication interfaces', TRUE, '2026-09-18T04:34:44.072Z', '2026-09-18T04:34:44.072Z') ON CONFLICT ("id") DO UPDATE SET "model" = EXCLUDED."model", "name" = EXCLUDED."name", "category" = EXCLUDED."category", "description" = EXCLUDED."description", "brand_image_url" = EXCLUDED."brand_image_url", "image_url" = EXCLUDED."image_url", "pdf_url" = EXCLUDED."pdf_url", "features" = EXCLUDED."features", "status" = EXCLUDED."status", "updated_at" = EXCLUDED."updated_at";
INSERT INTO "products" ("id", "model", "name", "category", "description", "brand_image_url", "image_url", "pdf_url", "features", "status", "created_at", "updated_at") VALUES ('162', 'AD-4961A', 'AD-4961A', 'Checkweigher', 'AD-4961A is a high-speed automatic checkweigher designed for accurate weight inspection on production lines, especially in food, cosmetics, logistics, and manufacturing applications. Its advanced HPDF vibration-elimination filter improves weighing accuracy at high conveyor speeds. The 7-inch color touchscreen provides easy operation and product setup. With IP65 protection, data recording, communication interfaces, and feedback control, it is suitable for demanding industrial inspection environments', 'https://res.cloudinary.com/hehl57yx/image/upload/v1789706382/weighing-balance/products/xrlh2ediiduy6fhsto8o.png', 'https://res.cloudinary.com/hehl57yx/image/upload/v1789706384/weighing-balance/products/bvrdeabsesm6pho9aouw.png', 'https://res.cloudinary.com/hehl57yx/image/upload/v1789706379/weighing-balance/products/pdfs/ad4961a.pdf', 'High-speed checkweighing with improved accuracy
7-inch color touchscreen for easy operation
IP65 dust- and water-resistant construction
Stores up to 1,000 product settings
RS-232C/RS-485, USB, wired LAN and wireless LAN connectivity', TRUE, '2026-09-18T04:39:49.504Z', '2026-09-18T04:39:49.505Z') ON CONFLICT ("id") DO UPDATE SET "model" = EXCLUDED."model", "name" = EXCLUDED."name", "category" = EXCLUDED."category", "description" = EXCLUDED."description", "brand_image_url" = EXCLUDED."brand_image_url", "image_url" = EXCLUDED."image_url", "pdf_url" = EXCLUDED."pdf_url", "features" = EXCLUDED."features", "status" = EXCLUDED."status", "updated_at" = EXCLUDED."updated_at";
INSERT INTO "products" ("id", "model", "name", "category", "description", "brand_image_url", "image_url", "pdf_url", "features", "status", "created_at", "updated_at") VALUES ('163', 'AD-4943B', 'AD-4943B', 'Checkweigher', 'AD-4943B is a heavy-duty checkweigher designed for accurate weighing and inspection of packaged products, bags, cartons, and other heavy items on production lines. It supports loads up to 30 kg with 5 g readability and uses a 7-inch color touchscreen for easy operation. The system can store up to 1,000 product settings and supports barcode-based product selection. It is suitable for final inspection, missing-item detection, logistics, food, cosmetics, and industrial production applications.', 'https://res.cloudinary.com/hehl57yx/image/upload/v1789706565/weighing-balance/products/utvxmxtcrxnzedjffifc.png', 'https://res.cloudinary.com/hehl57yx/image/upload/v1789706567/weighing-balance/products/fb4rnsrapogdqlposehy.png', 'https://res.cloudinary.com/hehl57yx/image/upload/v1789706543/weighing-balance/products/pdfs/AD4942BAD4943B-ADCC-01-AD2-221000.pdf', 'Heavy-duty weighing capacity up to 30 kg
5 g readability with 4,000-times/second sampling
7-inch color touchscreen with user-friendly operation
Stores up to 1,000 product settings
