INSERT INTO "products" ("id", "model", "name", "category", "description", "brand_image_url", "image_url", "pdf_url", "features", "status", "created_at", "updated_at") VALUES ('164', 'AD-4961 Series Checkweigher System', 'AD-4961 Series Checkweigher System', 'Checkweigher', 'The AD-4961 Series is a high-precision automatic checkweighing system designed for fast and reliable weight inspection on production lines. It uses a digital load cell and high-speed processing with HPDF vibration filtering to maintain accurate weighing at high conveyor speeds. The 7-inch color touchscreen provides easy operation, while the IP65 hygienic design makes the system suitable for demanding production environments. It is particularly suitable for food, packaging, manufacturing, and other automated inspection applications.', 'https://res.cloudinary.com/hehl57yx/image/upload/v1789706709/weighing-balance/products/rzxzemvobybheiltbgwg.png', 'https://res.cloudinary.com/hehl57yx/image/upload/v1789706711/weighing-balance/products/k0jboz2w8vodokvvd2bg.png', 'https://res.cloudinary.com/hehl57yx/image/upload/v1789706705/weighing-balance/products/pdfs/ad4961.pdf', 'High-precision weighing with resolution from 0.01 g to 0.1 g
High-level accuracy of up to 0.08 g (3σ) depending on model and conditions
7-inch color touchscreen with user-friendly operation
IP65 dust- and water-resistant hygienic design
Stores up to 1,000 product settings with USB data recording and multiple communication interfaces', TRUE, '2026-09-18T04:45:25.318Z', '2026-09-18T04:45:25.318Z') ON CONFLICT ("id") DO UPDATE SET "model" = EXCLUDED."model", "name" = EXCLUDED."name", "category" = EXCLUDED."category", "description" = EXCLUDED."description", "brand_image_url" = EXCLUDED."brand_image_url", "image_url" = EXCLUDED."image_url", "pdf_url" = EXCLUDED."pdf_url", "features" = EXCLUDED."features", "status" = EXCLUDED."status", "updated_at" = EXCLUDED."updated_at";
INSERT INTO "products" ("id", "model", "name", "category", "description", "brand_image_url", "image_url", "pdf_url", "features", "status", "created_at", "updated_at") VALUES ('165', 'AD-4976', 'AD-4976', 'Metal Detector', 'AD-4976 is a multi-frequency metal detector designed to detect metal contamination in packaged and processed products. It provides stable and sensitive detection while reducing false rejects through automatic frequency selection. The 7-inch color touchscreen offers intuitive operation, while its IP66-rated stainless-steel construction is suitable for hygienic production environments. The system can also inspect for missing iron-based oxygen absorbers along with metal contaminants.', 'https://res.cloudinary.com/hehl57yx/image/upload/v1789706970/weighing-balance/products/mkyzeoe2ewfsicktilg8.png', 'https://res.cloudinary.com/hehl57yx/image/upload/v1789706972/weighing-balance/products/s8yccnyqbmx4oyk5wjei.png', 'https://res.cloudinary.com/hehl57yx/image/upload/v1789706913/weighing-balance/products/pdfs/AD4976-ADCC-01-AD2-218000.pdf', 'Multi-frequency technology for reliable metal contamination detection
7-inch color touchscreen for easy operation
IP66 dust- and water-resistant construction
Automatic frequency selection to improve detection sensitivity
Modbus TCP/RTU, RS-232C, USB and Ethernet communication options', TRUE, '2026-09-18T04:49:53.716Z', '2026-09-18T04:49:53.716Z') ON CONFLICT ("id") DO UPDATE SET "model" = EXCLUDED."model", "name" = EXCLUDED."name", "category" = EXCLUDED."category", "description" = EXCLUDED."description", "brand_image_url" = EXCLUDED."brand_image_url", "image_url" = EXCLUDED."image_url", "pdf_url" = EXCLUDED."pdf_url", "features" = EXCLUDED."features", "status" = EXCLUDED."status", "updated_at" = EXCLUDED."updated_at";
INSERT INTO "products" ("id", "model", "name", "category", "description", "brand_image_url", "image_url", "pdf_url", "features", "status", "created_at", "updated_at") VALUES ('166', 'AD-4971 Metal Detection System', 'AD-4971 Metal Detection System', 'Metal Detector', 'AD-4971 is an inline metal detection system designed to detect metal contaminants in products and support safe, quality-controlled production. It features a hygienic IP65-rated design and automatic sensitivity setting for reliable inspection. The 7-inch color touchscreen provides simple operation, while the detachable conveyor belt makes cleaning and maintenance easier. With adjustable belt speeds and Modbus communication, it can be integrated into automated production lines.', 'https://res.cloudinary.com/hehl57yx/image/upload/v1789707096/weighing-balance/products/wvvfzrpku1nschhdy96o.png', 'https://res.cloudinary.com/hehl57yx/image/upload/v1789707099/weighing-balance/products/sn2lr1bfgw034cgr0rrk.png', 'https://res.cloudinary.com/hehl57yx/image/upload/v1789707078/weighing-balance/products/pdfs/ad4971.pdf', 'Detects ferrous and stainless-steel metal contaminants
IP65 dust- and water-resistant hygienic design
7-inch color touchscreen for easy operation
Adjustable conveyor belt speed of 10–60 m/min
Modbus RTU/TCP, Ethernet, USB and relay I/O for system integration', TRUE, '2026-09-18T04:52:05.846Z', '2026-09-18T04:52:05.846Z') ON CONFLICT ("id") DO UPDATE SET "model" = EXCLUDED."model", "name" = EXCLUDED."name", "category" = EXCLUDED."category", "description" = EXCLUDED."description", "brand_image_url" = EXCLUDED."brand_image_url", "image_url" = EXCLUDED."image_url", "pdf_url" = EXCLUDED."pdf_url", "features" = EXCLUDED."features", "status" = EXCLUDED."status", "updated_at" = EXCLUDED."updated_at";
INSERT INTO "products" ("id", "model", "name", "category", "description", "brand_image_url", "image_url", "pdf_url", "features", "status", "created_at", "updated_at") VALUES ('167', 'AD-4991 X-Ray Inspection System', 'AD-4991 X-Ray Inspection System for Contamination Detection', 'X-ray Inspection System', 'AD-4991 is a compact X-ray inspection system designed for reliable detection of foreign contaminants in packaged and processed products. It can detect materials such as metal, glass, calcified bone, PVC, Teflon, ceramic, and other dense contaminants. In addition to contamination detection, it supports shape, counting, positioning, and mass-estimation inspections. Its hygienic stainless-steel construction, IP66 inspection room, and quick-release belt make it suitable for food and manufacturing production lines', 'https://res.cloudinary.com/hehl57yx/image/upload/v1789707216/weighing-balance/products/heyngh0trk7j79u5wj8u.png', 'https://res.cloudinary.com/hehl57yx/image/upload/v1789707217/weighing-balance/products/ffvvo7ddtpqlonxxdzlh.png', 'https://res.cloudinary.com/hehl57yx/image/upload/v1789707207/weighing-balance/products/pdfs/AD4991-ADCC-02-AD2-202002GP.pdf', 'Detects metal, glass, bone, PVC, Teflon, ceramic, and other contaminants
15-inch color touchscreen with simple operator interface
Supports shape, counting, positioning, and mass-estimation inspections
IP66-rated inspection room with hygienic stainless-steel construction
Quick-release belt and curtains for easy cleaning and maintenance', TRUE, '2026-09-18T04:53:55.327Z', '2026-09-18T04:53:55.327Z') ON CONFLICT ("id") DO UPDATE SET "model" = EXCLUDED."model", "name" = EXCLUDED."name", "category" = EXCLUDED."category", "description" = EXCLUDED."description", "brand_image_url" = EXCLUDED."brand_image_url", "image_url" = EXCLUDED."image_url", "pdf_url" = EXCLUDED."pdf_url", "features" = EXCLUDED."features", "status" = EXCLUDED."status", "updated_at" = EXCLUDED."updated_at";

